const base = process.env.PLAYWRIGHT_BASE_URL ?? '';

const SEL = {
	frame: 'body',
	region1: '.bar-nav',
	region2: '.pill-brand',
	region3: '.workspaces',
	region4: '.hero',
	region5: '.keys-pane dl',
	region6: '.features',
	region7: '.layouts',
	region8: '.code-files',
	region9: '.others',
	region10: '.refuses ul',
	region11: '.repos',
	region12: '.then',
	region13: '.foot-body',
	region14: '.foot-links'
};

test('Linux · macOS · Android in Termux — A tiling window manager for the terminal.: frame matches the handoff', async ({
	page
}) => {
	await page.goto(`${base}/`);
	await expect(page.locator(SEL.frame)).toBeVisible();

	const frameStyle = await page.locator(SEL.frame).evaluate((node) => {
		const cs = getComputedStyle(node);
		return {
			display: cs.display
		};
	});
	expect(frameStyle.display).toBe('block');
});

test('Linux · macOS · Android in Termux — A tiling window manager for the terminal.: region1 matches the handoff', async ({
	page
}) => {
	await page.goto(`${base}/`);
	await expect(page.locator(SEL.region1)).toBeVisible();

	const region1Style = await page.locator(SEL.region1).evaluate((node) => {
		const cs = getComputedStyle(node);
		return {
			display: cs.display,
			flexWrap: cs.flexWrap,
			alignItems: cs.alignItems,
			rowGap: cs.rowGap,
			columnGap: cs.columnGap,
			paddingTop: cs.paddingTop,
			paddingRight: cs.paddingRight,
			paddingBottom: cs.paddingBottom,
			paddingLeft: cs.paddingLeft,
			fontSize: cs.fontSize,
			lineHeight: cs.lineHeight,
			maxWidth: cs.maxWidth
		};
	});
	expect(region1Style.display).toBe('flex');
	expect(region1Style.flexWrap).toBe('wrap');
	expect(region1Style.alignItems).toBe('center');
	expect(region1Style.rowGap).toBe('8px');
	expect(region1Style.columnGap).toBe('12px');
	expect(region1Style.paddingTop).toBe('10px');
	expect(region1Style.paddingRight).toBe('16px');
	expect(region1Style.paddingBottom).toBe('10px');
	expect(region1Style.paddingLeft).toBe('16px');
	expect(region1Style.fontSize).toBe('14px');
	expect(region1Style.lineHeight).toBe('22.4px');
	expect(region1Style.maxWidth).toBe('1200px');
});

